def drawdown_period(dates, prices):
    # return (peak_date, trough_date, depth) for the maximum drawdown
    peak_i = 0
    best = (dates[0], dates[0], 0.0)
    for i, p in enumerate(prices):
        if p > prices[peak_i]:
            peak_i = i
        depth = (prices[peak_i] - p) / prices[peak_i]
        if depth > best[2]:
            best = (dates[peak_i], dates[i], depth)
    return best

print(drawdown_period(["02/03", "03/03", "04/03", "05/03", "06/03"],
